describe("severityCountsFromObservations", () => {
  it("counts present observations only, through normalizeSeverity", () => {
    const obs: Pick<Observation, "present" | "severity">[] = [
      { present: 1, severity: "CRITICAL" },
      { present: 1, severity: "critical" },
      { present: 1, severity: "INFORMATIONAL" },
      { present: 1, severity: "nonsense" },
      { present: 1, severity: null },
      { present: 0, severity: "CRITICAL" }, // resolved-by-disappearance: not in this scan
    ];
    expect(severityCountsFromObservations(obs))
      .toEqual({ CRITICAL: 2, INFO: 1, UNKNOWN: 2 });
    expect(severityCountsFromObservations([])).toEqual({});
  });

  it("matches the fixture's own first scan", () => {
    const state = emptyState();
    const { observations } = persistFlatScan(state, fx.scans.s1.records, {
      scope: "sca", mode: "live", scanId: fx.scans.s1.id,
    });
    // s1 lists one CRITICAL (A) and one HIGH (B); both are present.
    expect(severityCountsFromObservations(observations)).toEqual({ CRITICAL: 1, HIGH: 1 });
  });
});
